// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

/// @notice Factory for deploying ERC1967 proxies with admin and upgrade logic.
/// @author Solady (https://github.com/vectorized/solady)
contract ERC1967Factory {
    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                         IMMUTABLES                         */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @dev The ERC1967 implementation slot.
    bytes32 internal constant _ERC1967_IMPLEMENTATION_SLOT =
        0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                          ERRORS                            */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @dev The caller is not authorized.
    error Unauthorized();

    /// @dev The deployment failed.
    error DeploymentFailed();

    /// @dev The upgrade failed.
    error UpgradeFailed();

    /// @dev The salt does not start with the caller.
    error SaltDoesNotStartWithCaller();

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                          EVENTS                            */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @dev Emitted when a proxy is deployed.
    event Deployed(address indexed proxy, address indexed implementation, address indexed admin);

    /// @dev Emitted when a proxy's admin is changed.
    event AdminChanged(address indexed proxy, address indexed admin);

    /// @dev Emitted when a proxy's implementation is upgraded.
    event Upgraded(address indexed proxy, address indexed implementation);

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                     ADMIN OPERATIONS                       */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Retrieves the admin address associated with a given proxy address.
    ///
    /// @param proxy The address of the proxy contract.
    /// @return admin The address of the admin associated with the proxy.
    function adminOf(address proxy) public view returns (address admin) {
        assembly {
            // The admin is stored at the storage slot computed by shifting the proxy address left by 96 bits.
            mstore(0x00, shl(96, proxy))
            admin := sload(keccak256(0x00, 0x20))
        }
    }

    /// @notice Changes the admin of a proxy contract. Only the current admin can call this function.
    ///
    /// @param proxy The address of the proxy contract whose admin is to be changed.
    /// @param admin The address of the new admin.
    function changeAdmin(address proxy, address admin) public {
        assembly {
            // Compute the storage slot for the admin.
            mstore(0x00, shl(96, proxy))
            let s := keccak256(0x00, 0x20)
            // Check if the caller is the current admin.
            if iszero(eq(caller(), sload(s))) {
                mstore(0x00, 0x82b42900) // `Unauthorized()`.
                revert(0x1c, 0x04)
            }
            // Store the new admin address.
            sstore(s, admin)
            // Emit the `AdminChanged` event.
            mstore(0x00, proxy)
            mstore(0x20, admin)
            log3(0x00, 0x40, 0x7e644d79422f17c01e4894b5f4f588d331ebfa28653d42ae832dc59e38c9798f, mload(0x00), mload(0x20))
        }
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                     UPGRADE OPERATIONS                     */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Upgrades the implementation of a proxy contract to a new address.
    ///
    /// @param proxy The address of the proxy contract to be upgraded.
    /// @param implementation The address of the new implementation contract.
    function upgrade(address proxy, address implementation) public payable {
        upgradeAndCall(proxy, implementation, _emptyData());
    }

    /// @notice Upgrades the implementation of a proxy contract and calls a function on the new implementation.
    ///
    /// @param proxy The address of the proxy contract to be upgraded.
    /// @param implementation The address of the new implementation contract.
    /// @param data The calldata to be passed to the new implementation after the upgrade.
    function upgradeAndCall(address proxy, address implementation, bytes calldata data) public payable {
        assembly {
            // Compute the admin storage slot.
            mstore(0x00, shl(96, proxy))
            let adminSlot := keccak256(0x00, 0x20)
            // Check if the caller is the admin.
            if iszero(eq(caller(), sload(adminSlot))) {
                mstore(0x00, 0x82b42900) // `Unauthorized()`.
                revert(0x1c, 0x04)
            }
            // Prepare the calldata for the upgrade.
            // Store the implementation address and the implementation slot in memory.
            mstore(0x14, implementation) // Store implementation at memory offset 0x14 (left-padded to 32 bytes).
            mstore(0x34, _ERC1967_IMPLEMENTATION_SLOT) // Store the ERC1967 implementation slot.
            mstore(0x00, 0x5c60da1b) // `upgradeToAndCall(address)` function selector.
            // Copy the provided data into memory.
            // The calldata offset is stored at 0x74, and the data follows.
            calldatacopy(0x74, data.offset, data.length)
            // Attempt to upgrade the proxy by calling the proxy with the prepared calldata.
            let success := call(gas(), proxy, 0, 0x10, add(0x54, data.length), 0x00, 0x00)
            if iszero(success) {
                // If there is no returndata, revert with `UpgradeFailed`.
                if iszero(returndatasize()) {
                    mstore(0x00, 0x55299b49) // `UpgradeFailed()`.
                    revert(0x1c, 0x04)
                }
                // Otherwise, bubble up the returned error.
                returndatacopy(0x00, 0x00, returndatasize())
                revert(0x00, returndatasize())
            }
            // Emit the `Upgraded` event.
            mstore(0x00, proxy)
            mstore(0x20, implementation)
            log3(0x00, 0x40, 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc, mload(0x00), mload(0x20))
        }
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                     DEPLOY OPERATIONS                      */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Deploys a new proxy contract with the specified implementation and admin address.
    ///
    /// @param implementation The address of the implementation contract to be used by the proxy.
    /// @param admin The address of the admin who will manage the proxy.
    /// @return proxy The address of the newly deployed proxy contract.
    function deploy(address implementation, address admin) public payable returns (address proxy) {
        proxy = deployAndCall(implementation, admin, _emptyData());
    }

    /// @notice Deploys a proxy contract and calls a function on it with the provided data.
    ///
    /// @param implementation The address of the implementation contract to be used by the proxy.
    /// @param admin The address of the admin who will manage the proxy.
    /// @param data The calldata to be passed to the proxy after deployment.
    /// @return proxy The address of the deployed proxy contract.
    function deployAndCall(address implementation, address admin, bytes calldata data) public payable returns (address proxy) {
        proxy = _deploy(implementation, admin, bytes32(0), false, data);
    }

    /// @notice Deploys a deterministic proxy contract using the provided implementation, admin, and salt.
    ///
    /// @param implementation The address of the implementation contract to be used by the proxy.
    /// @param admin The address of the admin who will manage the proxy.
    /// @param salt A unique salt value to ensure deterministic deployment.
    /// @return proxy The address of the deployed proxy contract.
    function deployDeterministic(address implementation, address admin, bytes32 salt) public payable returns (address proxy) {
        proxy = deployDeterministicAndCall(implementation, admin, salt, _emptyData());
    }

    /// @notice Deploys a deterministic proxy contract with a given implementation, admin, salt, and optional initialization data.
    ///
    /// @param implementation The address of the implementation contract.
    /// @param admin The address of the admin for the proxy contract.
    /// @param salt A unique salt value used to deterministically generate the proxy address.
    /// @param data Optional initialization data to be passed to the proxy after deployment.
    /// @return proxy The address of the deployed proxy contract.
    function deployDeterministicAndCall(address implementation, address admin, bytes32 salt, bytes calldata data) public payable returns (address proxy) {
        assembly {
            // Check if the salt starts with the zero address or matches the caller's address.
            let s := shr(96, salt)
            if iszero(or(iszero(s), eq(s, caller()))) {
                mstore(0x00, 0x2f634836) // `SaltDoesNotStartWithCaller()`.
                revert(0x1c, 0x04)
            }
        }
        proxy = _deploy(implementation, admin, salt, true, data);
    }

    /// @notice Deploys a proxy contract using either `create` or `create2` depending on the `useSalt` flag.
    ///
    /// @param implementation The address of the implementation contract.
    /// @param admin The address of the admin for the proxy contract.
    /// @param salt A unique salt value used for deterministic deployment.
    /// @param useSalt Whether to use `create2` with the provided salt.
    /// @param data Optional initialization data to be passed to the proxy after deployment.
    /// @return proxy The address of the deployed proxy contract.
    function _deploy(address implementation, address admin, bytes32 salt, bool useSalt, bytes calldata data) internal returns (address proxy) {
        // Retrieve the initialization code for the proxy.
        bytes32 m = _initCode();
        assembly {
            // Deploy the proxy contract.
            // If `useSalt` is false, use `create` to deploy the proxy.
            // If `useSalt` is true, use `create2` with the provided `salt` to deploy the proxy.
            proxy := create2(0x00, add(m, 0x20), mload(m), salt)
            // Revert if the proxy creation fails.
            if iszero(proxy) {
                mstore(0x00, 0x55299b49) // `DeploymentFailed()`.
                revert(0x1c, 0x04)
            }
            // Set up the calldata to configure the proxy's implementation.
            // Store the implementation address and the implementation slot in memory.
            mstore(0x14, implementation) // Store implementation at memory offset 0x14.
            mstore(0x34, _ERC1967_IMPLEMENTATION_SLOT) // Store the ERC1967 implementation slot.
            mstore(0x00, 0x5c60da1b) // `upgradeToAndCall(address)` function selector.
            // Copy the provided `data` into memory for the proxy initialization.
            calldatacopy(0x74, data.offset, data.length)
            // Call the proxy to set the implementation and revert if the call fails.
            let success := call(gas(), proxy, callvalue(), 0x10, add(0x54, data.length), 0x00, 0x00)
            if iszero(success) {
                // If no returndata is available, revert with the `DeploymentFailed` error.
                if iszero(returndatasize()) {
                    mstore(0x00, 0x55299b49) // `DeploymentFailed()`.
                    revert(0x1c, 0x04)
                }
                // Otherwise, bubble up the returned error.
                returndatacopy(0x00, 0x00, returndatasize())
                revert(0x00, returndatasize())
            }
            // Store the admin address for the proxy in storage.
            mstore(0x00, shl(96, proxy))
            sstore(keccak256(0x00, 0x20), admin)
            // Emit the `Deployed` event with the proxy, implementation, and admin addresses.
            mstore(0x00, proxy)
            mstore(0x20, implementation)
            mstore(0x40, admin)
            log3(0x00, 0x60, 0x20a866fbb750403390099e262e5c8d40834f3e0c4096c0400da0576057e08c80, mload(0x00), mload(0x20))
        }
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                    DETERMINISTIC HELPERS                   */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Predicts the deterministic address for a contract deployment using the CREATE2 opcode.
    ///
    /// @param salt A unique salt value used to generate the deterministic address.
    /// @return predicted The predicted address of the contract that would be deployed with the given salt.
    function predictDeterministicAddress(bytes32 salt) public view returns (address predicted) {
        bytes32 hash = initCodeHash();
        assembly {
            // Compute the deterministic address.
            // Write the prefix `0xff` to memory.
            mstore8(0x00, 0xff)
            // Store the deployer address.
            mstore(0x01, shl(96, address()))
            // Store the salt.
            mstore(0x15, salt)
            // Store the bytecode hash.
            mstore(0x35, hash)
            // Compute the keccak256 hash of the concatenated data to derive the predicted address.
            predicted := keccak256(0x00, 0x55)
        }
    }

    /// @notice Returns the keccak256 hash of the initialization code.
    ///
    /// @return result The keccak256 hash of the proxy initialization code.
    function initCodeHash() public view returns (bytes32 result) {
        bytes32 m = _initCode();
        assembly {
            // Compute the keccak256 hash of the initialization code.
            result := keccak256(add(m, 0x20), mload(m))
        }
    }

    /// @notice Returns the initialization code for the ERC1967 proxy.
    ///
    /// @return m The initialization code as a bytes32 value (packed with length).
    function _initCode() internal view returns (bytes32 m) {
        // The proxy runtime code handles delegate calls and manages the contract's state.
        // The runtime code is generated based on the factory's address to optimize for zero bytes.
        assembly {
            // Load the free memory pointer into `m`.
            m := mload(0x40)
            // Generate the runtime code based on the factory's address.
            // Depending on the number of leading zero bytes in the factory's address,
            // different runtime code is generated for gas optimization.
            let factory := address()
            // The runtime code includes:
            // - Creation code to deploy the contract.
            // - Runtime code to handle delegate calls, check the caller, copy calldata, and manage state.
            // - Logic to handle successful and failed delegate calls, including reverting or returning data.
            // - Logic to set a new implementation if the caller is the factory.
            //
            // The proxy runtime code pattern:
            // - If caller is factory, allow setting implementation
            // - Otherwise, delegatecall to implementation
            //
            // Implementation slot: 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc
            //
            // We generate compact bytecode that depends on the factory address.
            // Count the number of leading zero bytes in the factory address for optimization.
            let z := 0
            // Check each byte of the 20-byte address
