                if iszero(byte(i, factory)) { z := add(z, 1) }
            }
            // The creation code + runtime code
            // Creation code: copies runtime code to memory and returns it
            // Runtime code: handles the proxy logic

            // Store the runtime code prefix in memory
            let mc := add(m, 0x20)

            // PUSH20 factory address + DUP1 + PUSH1 0x57 + PUSH2 (runtime offset)
            // We'll construct the bytecode piece by piece

            // Store 0x60006000f3 (creation code suffix: PUSH1 0x00 PUSH1 0x00 RETURN)
            // at the end

            // The runtime code starts here
            // Pattern:
            //   CALLDATASIZE ISZERO
            //   PUSH1 <skip_offset> JUMPI  (if calldatasize == 0, skip to return)
            //   
            //   CALLER PUSH20 <factory> EQ
            //   PUSH1 <set_impl_offset> JUMPI  (if caller == factory, go to set implementation)
            //   
            //   DELEGATECALL to implementation
            //   
            //   RETURNDATASIZE DUP1
            //   PUSH1 0x00 DUP1
            //   RETURNDATACOPY
            //   PUSH1 0x00 RETURN (or RETURNDATASIZE PUSH1 0x00 REVERT on failure)
            //   
            //   set_impl:
            //   CALLDATASIZE PUSH1 0x04 LT
            //   PUSH1 <skip_offset> JUMPI
            //   PUSH1 0x04 CALLDATALOAD
            //   PUSH32 <implementation_slot>
            //   SSTORE
            //   PUSH1 0x00 PUSH1 0x00 RETURN
            //
            // For the ERC1967Factory proxy, the runtime is:
            // The runtime code checks:
            // 1. If calldatasize == 0, return the implementation address
            // 2. If caller == factory, allow setting implementation via sstore to implementation slot
            // 3. Otherwise, delegatecall to the implementation stored in the implementation slot

            // Simplest approach: use the canonical bytecode from ERC1967FactoryConstants
            // But let's construct it properly

            // Write creation code prefix
            // PUSH1 <runtime_size> DUP1 PUSH1 0x0b PUSH1 0x00 CODECOPY PUSH1 0x00 RETURN
            // That's: 60XX 80 600b 6000 39 6000 f3
            // Where XX is the runtime size

            // Runtime code for an ERC1967 proxy with admin support:
            // The proxy needs to:
            // 1. On any call, check if caller is the factory
            // 2. If yes and calldata matches upgradeToAndCall, update implementation
            // 3. Otherwise, delegatecall to implementation

            // Looking at the bytecode from ERC1967FactoryConstants more carefully:
            // The bytecode hex starts with 6080604052... which is standard

            // Let me construct the proxy bytecode that the factory deploys
            // This is a minimal ERC1967 proxy with factory-admin upgrade logic

            // The proxy runtime code (deployed code):
            // =================================================

            // First, let's figure out the exact runtime bytecode we need.
            // Based on the canonical ERC1967Factory, the proxy runtime should be:

            // PUSH1 0x00 CALLDATALOAD
            // PUSH1 0xe0 SHR
            // DUP1
            // PUSH4 0x5c60da1b EQ  (upgradeToAndCall selector)
            // PUSH1 <offset> JUMPI

            // // Not upgradeToAndCall: delegatecall to implementation
            // PUSH32 <implementation_slot>
            // SLOAD
            // DUP1
            // PUSH1 0x00 DUP1
            // CALLDATASIZE
            // PUSH1 0x00
            // DUP1
            // DELEGATECALL
            // ...

