            i := add(i, 1)
            mstore8(add(rc, i), 0x00)
            i := add(i, 1)

            // RETURN
            mstore8(add(rc, i), 0xf3)
            i := add(i, 1)

            // Now update the creation code with the actual runtime size
            // The runtime code size is i bytes
            // Update the PUSH1 in creation code at offset mc+1
            mstore8(add(mc, 1), i)

            // Store the length of the entire init code (creation + runtime)
            let totalLen := add(11, i) // 11 bytes creation code + i bytes runtime
            mstore(m, totalLen)

            // Update free memory pointer
            mstore(0x40, add(add(m, 0x20), totalLen))
        }
    }

    /// @notice Internal function that returns an empty bytes calldata.
    ///
    /// @return data The empty bytes calldata.
    function _emptyData() internal pure returns (bytes calldata data) {
        assembly {
            data.length := 0
        }
    }
}
